CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `ukicon26`.`supplier_attendees` AS select row_number() OVER (ORDER BY `ukicon26`.`attendees`.`Organization` )  AS `ID`,`ukicon26`.`attendees`.`ID` AS `Attendee_ID`,`ukicon26`.`attendees`.`FirstName` AS `FirstName`,`ukicon26`.`attendees`.`LastName` AS `LastName`,concat(trim(`ukicon26`.`attendees`.`FirstName`),' ',trim(`ukicon26`.`attendees`.`LastName`)) AS `FullName`,`ukicon26`.`attendees`.`Organization` AS `Organization`,`ukicon26`.`attendees`.`RegistrationType` AS `RegistrationType`,`ukicon26`.`attendees`.`Email` AS `Email`,`ukicon26`.`attendees`.`TableAllocated` AS `TableAllocated`,`ukicon26`.`attendees`.`FullMatch` AS `FullMatch`,`ukicon26`.`attendees`.`PartialMatch` AS `PartialMatch`,`ukicon26`.`attendees`.`NumberOfMeetings` AS `NumberOfMeetings` from `ukicon26`.`attendees` where (`ukicon26`.`attendees`.`RegistrationType` = 'Supplier B2B Attendee') group by `ukicon26`.`attendees`.`ID` order by `ukicon26`.`attendees`.`Organization`;
